func requireServedParitySettlementPostconditionsWithDebug(t *testing.T, endpoint string, db *sql.DB, backend, runID string, scenario servedparity.Scenario, debug func() string) {
	t.Helper()
	var last cliapp.DiagnosticRunDiagnosisResult
	deadline := time.Now().Add(servedProofPollDeadline)
	for time.Now().Before(deadline) {
		var result cliapp.DiagnosticRunDiagnosisResult
		requireServedJSONRPCResult(t, endpoint, "run.diagnose", map[string]any{"run_id": runID}, &result)
		last = result
		if result.Run.RunID != runID || result.TestQuiescence == nil {
			time.Sleep(50 * time.Millisecond)
			continue
		}
		counts := servedparity.SettlementCounts{NonTerminalDeliveries: cliapp.IntPointerValue(result.TestQuiescence.ActiveDeliveries), PendingPipelineEvents: cliapp.IntPointerValue(result.TestQuiescence.UnsettledPipelineEvents), UnfiredDueTimers: cliapp.IntPointerValue(result.TestQuiescence.DueTimers)}
		if len(servedparity.SettlementPostconditionFailures(scenario, counts)) == 0 {
			return
		}
		time.Sleep(50 * time.Millisecond)
	}
	extra := ""
	if debug != nil {
		extra = "\n" + debug()
	} else {
		extra = "\n" + servedEventPublishDebugSummary(t, db, backend, runID)
	}
	t.Fatalf("served parity scenario %s settlement did not quiesce for run %s: ready=%v active_deliveries=%d unsettled_pipeline_events=%d due_timers=%d active_session_leases=%d%s", scenario.ID, runID, cliapp.BoolPointerValue(last.TestQuiescence.Ready), cliapp.IntPointerValue(last.TestQuiescence.ActiveDeliveries), cliapp.IntPointerValue(last.TestQuiescence.UnsettledPipelineEvents), cliapp.IntPointerValue(last.TestQuiescence.DueTimers), cliapp.IntPointerValue(last.TestQuiescence.ActiveSessionLeases), extra)
}

