	t.Helper()
	db := rt.DB
	backend := rt.Backend
	ctx := context.Background()
	runID := uuid.NewString()
	eventID := uuid.NewString()
	now := time.Now().UTC()
	bundleHash := rt.Runtime.Options.SourceArtifactFact.BundleHash()
	if bundleHash == "" || bundleHash != rt.BundleHash {
		t.Fatalf("%s served runtime source artifact = %q, want exact hash %q", backend, bundleHash, rt.BundleHash)
	}
	var selectedStore storetest.RunFixtureStore
	switch backend {
	case "postgres":
		if rt.Postgres == nil {
			t.Fatal("served postgres store owner is required for run-control seed")
		}
		selectedStore = rt.Postgres
	case "sqlite":
		if rt.SQLite == nil {
			t.Fatal("served sqlite store owner is required for run-control seed")
		}
		selectedStore = rt.SQLite
	default:
		t.Fatalf("unknown proof backend %q", backend)
	}
	storetest.RequireRun(t, ctx, selectedStore, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: runID, StartedAt: now, BundleHash: bundleHash})
	event := eventtest.PersistedProjection(eventID, "control.stop.pending", "test", "", json.RawMessage(`{}`), 0, runID, "", events.EventEnvelope{Scope: events.EventScopeGlobal}, now)
	storetest.CommitSemanticEventWithInitialFacts(t, ctx, selectedStore, event, []events.DeliveryRoute{{Recipient: events.MustAgentDeliveryRecipient("agent-pending"), AgentIdentity: agentidentitytest.RootRuntimeForRun(t, runID, "agent-pending", "serveapp-test")}}, runtimepipelineobligation.ScopeSubscribed, storetest.AcknowledgedPipelineDisposition())
	if got := servedEventPublishReceiptOutcomeCount(t, db, backend, eventID, "platform", "pipeline", "success"); got != 1 {
		t.Fatalf("%s seeded pipeline receipt count for event=%s = %d, want 1\n%s", backend, eventID, got, servedEventPublishDebugSummary(t, db, backend, runID))
	}
	entityID, cardID := seedServedRunControlDecisionCard(t, rt, runID, now)
	return runID, eventID, entityID, cardID
}

