	deadline := time.Now().Add(servedProofPollDeadline)
	for time.Now().Before(deadline) {
		var entityID string
		err := db.QueryRowContext(context.Background(), `
			SELECT entity_id::text
			FROM entity_state
			WHERE run_id = $1::uuid
			  AND entity_type = 'order'
