								if !t.Failed() {
									return
								}
								rows, err := rt.DB.Query(`SELECT failure FROM dead_letters WHERE original_event_id IN (SELECT event_id FROM events WHERE run_id=$1)`, seed.RunID)
								if err != nil {
									t.Logf("failure readback: %v", err)
									return
								}
								defer rows.Close()
								for rows.Next() {
