		}
		if completed >= turns {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("agent turns=%d want=%d\n%s", completed, turns, servedEventPublishDebugSummary(t, rt.DB, rt.Backend, runID))
		}
		time.Sleep(20 * time.Millisecond)
	}
