			t.Cleanup(func() {
				once.Do(func() {
					close(release)
				})
			})
			seed := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": "work.seeded", "bundle_hash": rt.BundleHash, "payload": map[string]any{"seed": true}, "idempotency_key": "receiver-seed"})
