			if err != nil {
				t.Fatal(err)
			}
			if n, err := result.RowsAffected(); err != nil || n != 1 {
				t.Fatalf("invalidate exact receiver: %d %v", n, err)
			}
			once.Do(func() {
				close(release)
			})
			waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, seed.RunID)
			if err := rt.DB.QueryRow(`SELECT status FROM event_deliveries WHERE delivery_id=$1`, claim.DeliveryID()).Scan(&status); err != nil {
				t.Fatal(err)
			}
			if status != "dead_letter" {
				t.Fatalf("receiver rejection left claimed work: %s", status)
			}
			var outcomes int
			if err := rt.DB.QueryRow(`SELECT count(*) FROM (SELECT delivery_id, claim_version, outcome, reason_code, failure, side_effects, duration_ms, completed_at AS settled_at FROM event_delivery_attempts WHERE closure_kind='settled') WHERE delivery_id=$1 AND outcome='dead_letter'`, claim.DeliveryID()).Scan(&outcomes); err != nil {
				t.Fatal(err)
			}
			if outcomes != 1 {
				t.Fatalf("terminal receiver outcomes = %d, want one", outcomes)
			}
			var afterFields, afterTarget string
			if err := rt.DB.QueryRow(`SELECT CAST(fields AS TEXT) FROM entity_state WHERE run_id=$1 AND entity_id=$2`, seed.RunID, owner.Route().EntityID).Scan(&afterFields); err != nil {
				t.Fatal(err)
			}
			if beforeFields != afterFields {
				t.Fatalf("rejected receiver mutated business fields: %s -> %s", beforeFields, afterFields)
			}
			var afterState string
			if err := rt.DB.QueryRow(`SELECT current_state FROM flow_instances WHERE run_id=$1 AND entity_id=$2`, seed.RunID, owner.Route().EntityID).Scan(&afterState); err != nil || afterState != "done" {
				t.Fatalf("rejected receiver changed canonical progress: state=%q err=%v", afterState, err)
			}
			if err := rt.DB.QueryRow(`SELECT CAST(delivery_target_route AS TEXT) FROM event_deliveries WHERE delivery_id=$1`, claim.DeliveryID()).Scan(&afterTarget); err != nil {
				t.Fatal(err)
			}
			if afterTarget != rawTarget {
				t.Fatal("receiver failure replaced its committed target")
			}
			duplicate := requireServedEventPublishRPCResult(t, rt.Endpoint, params)
			if duplicate.EventID != published.EventID {
				t.Fatal("exact duplicate created another event")
			}
			if err := rt.DB.QueryRow(`SELECT count(*) FROM (SELECT delivery_id, claim_version, outcome, reason_code, failure, side_effects, duration_ms, completed_at AS settled_at FROM event_delivery_attempts WHERE closure_kind='settled') WHERE delivery_id=$1`, claim.DeliveryID()).Scan(&outcomes); err != nil {
				t.Fatal(err)
			}
			if outcomes != 1 {
				t.Fatalf("duplicate receiver settlement: %d outcomes", outcomes)
			}
			waitServedEventPublishReceiptOutcomeCount(t, rt.DB, rt.Backend, published.EventID, "platform", "pipeline", "success", 1)
			requireReceiverPublicReadback(t, rt, seed.RunID)
		})
	}
}

