			requireServedEntityReadback(t, rt.Endpoint, run, run, "done")
			requireServedJSONRPCResult(t, rt.Endpoint, "entity.get", map[string]any{"run_id": run, "entity_id": run}, &public)
			if public.Fields["score"] != float64(10) {
				t.Fatalf("republication lost numeric agreement: %#v", public)
			}
			requireServedParitySettlementPostconditions(t, rt.Endpoint, rt.DB, rt.Backend, run, servedparity.Scenario{ID: "numeric-setup-republication", Postconditions: []servedparity.Postcondition{servedparity.PostconditionNoNonTerminalDeliveries, servedparity.PostconditionNoPendingPipelineEvents, servedparity.PostconditionNoUnfiredDueTimers}})
		})
	}
}

